@section('content')
<div class="pm-heading"><div><p class="pm-eyebrow"><a href="{{ route('pms.projects.show',$project) }}">{{ $project->key }}</a> / BOARD</p><h1>{{ $project->name }} board</h1><p>Drag a card to a permitted next status. Rules are checked on the server.</p></div><a class="pm-button secondary" href="{{ route('pms.projects.show',$project) }}">Project details →</a></div>
<div class="pm-board" id="pm-board">@foreach(\App\Services\PmsWorkflow::STATUSES as $status)<section class="pm-column" data-status="{{ $status }}"><div class="pm-column-head"><h2>{{ $status }}</h2><span>{{ $issues->getCollection()->where('status',$status)->count() }}</span></div><div class="pm-column-body">@foreach($issues->getCollection()->where('status',$status) as $issue)<article class="pm-card" draggable="true" data-id="{{ $issue->id }}" data-version="{{ $issue->lock_version }}" data-url="{{ route('pms.issues.transition',$issue) }}"><a href="{{ route('pms.issues.show',$issue) }}">{{ $issue->reference }}</a><strong>{{ $issue->summary }}</strong><div><span>{{ \App\Support\PmsPriority::label($issue->priority) }}</span><small>{{ $issue->developer?->name ?: 'Unassigned' }}</small></div></article>@endforeach</div></section>@endforeach</div>
