@section('scripts')<script>
let dragged=null;document.querySelectorAll('.pm-card').forEach(card=>card.addEventListener('dragstart',e=>{dragged=card;e.dataTransfer.effectAllowed='move'}));
document.querySelectorAll('.pm-column').forEach(column=>{column.addEventListener('dragover',e=>e.preventDefault());column.addEventListener('drop',async e=>{e.preventDefault();if(!dragged)return;const message=document.getElementById('pm-board-message');const reason=['Reopen','QAT Dependency'].includes(column.dataset.status)?prompt('Reason for this transition:'):'';if(reason===null)return;const body=new URLSearchParams({status:column.dataset.status,lock_version:dragged.dataset.version,reason});try{const response=await fetch(dragged.dataset.url,{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,'Accept':'application/json','Content-Type':'application/x-www-form-urlencoded'},body});if(!response.ok){const data=await response.json();throw new Error(data.message||Object.values(data.errors||{})[0]?.[0]||'Transition rejected');}location.reload()}catch(error){message.textContent=error.message;message.hidden=false;message.scrollIntoView({behavior:'smooth'})}})});
</script>@endsection
